export const EXTRA_PATTERNS: Pattern[] = [
  [/^(\d+) links?$/, (m) => `${m[1]} روابط`],
  [/^Showing the rows with (\S+) on the other side\.$/, (m) => `تُعرض الصفوف التي فيها ${m[1]} في الطرف الآخر.`],
  [/^Partner group (\d+)$/, (m) => `المجموعة الشريكة ${m[1]}`],
  [/^Role (\d+)$/, (m) => `الدور ${m[1]}`],
  [/^Partner (\d+): pick the partner group, or remove the row$/, (m) => `الشريك ${m[1]}: اختر المجموعة الشريكة أو أزل الصف`],
  [/^· (.+)$/, (m) => `· ${trS(m[1])}`],
  [/^(\d+) partner links$/, (m) => `روابط شركاء: ${m[1]}`],
  [/^from (\d+) work groups?$/, (m) => `من ${m[1]} من مجموعات العمل`],
  [/^(\d+) under way · (\d+) upcoming$/, (m) => `جارية: ${m[1]} · قادمة: ${m[2]}`],
  [/^(.+) signed in$/, (m) => `سجّل ${m[1]} الدخول`],
  [/^(.+) signed out$/, (m) => `سجّل ${m[1]} الخروج`],
  [/^(\S+): activity (added|updated|removed)$/, (m) => `${m[1]}: ${{ added: 'أُضيف نشاط', updated: 'حُدّث نشاط', removed: 'أُزيل نشاط' }[m[2]]}`],
  [/^Group member: (added|updated|deleted) (.+)$/, (m) => `عضو مجموعة: ${{ added: 'أُضيف', updated: 'حُدّث', deleted: 'حُذف' }[m[1]]} ${m[2]}`],
  [/^(.+) restored the backup of (.+) \((\d+) records\)$/, (m) => `استعاد ${m[1]} النسخة الاحتياطية بتاريخ ${m[2]} (${m[3]} سجلًا)`],
  [/^(.+) went back to the restore point of (.+)$/, (m) => `رجع ${m[1]} إلى نقطة الاستعادة بتاريخ ${m[2]}`],
  [/^Before restoring the backup of (.+)$/, (m) => `قبل استعادة النسخة الاحتياطية بتاريخ ${m[1]}`],
  [/^Downloaded the restore point of (.+)$/, (m) => `نزّل نقطة الاستعادة بتاريخ ${m[1]}`],
  [/^(?:The )?(planned start|planned finish|start|finish|proposed date) must be between (.+) and (.+)\.$/i, (m) => `${({ 'planned start': 'البدء المخطط', 'planned finish': 'الانتهاء المخطط', start: 'البدء', finish: 'الانتهاء', 'proposed date': 'التاريخ المقترح' } as Record<string, string>)[m[1].toLowerCase()]} يجب أن يكون بين ${m[2]} و${m[3]}.`],
  [/^(\d+) entries$/, (m) => `${m[1]} إدخال`],
  [/^ ?(\d+) fields$/, (m) => `${m[1]} حقول`],
  [/^(\d+) open errors$/, (m) => `أخطاء مفتوحة: ${m[1]}`],
  [/^Resolve all (\d+) shown$/, (m) => `تعليم الـ ${m[1]} المعروضة كمحلولة`],
  [/^Failed sign-in for (.+?)( \(account now locked\))?$/, (m) => `محاولة دخول فاشلة لـ ${m[1]}${m[2] ? ' (قُفل الحساب الآن)' : ''}`],
  [/^Failed sign-in: (.+)$/, (m) => `محاولة دخول فاشلة: ${m[1]}`],
  [/^Account locked after repeated failed sign-ins: (.+)$/, (m) => `قُفل الحساب بعد محاولات دخول فاشلة متكررة: ${m[1]}`],
  [/^Sign-in refused: account locked: (.+)$/, (m) => `رُفض الدخول لأن الحساب مقفل: ${m[1]}`],
  [/^Request refused: no permission: (.+)$/, (m) => `طلب مرفوض لعدم وجود صلاحية: ${m[1]}`],
  [/^Too many requests \(rate limit\): (.+)$/, (m) => `طلبات كثيرة جدًا (حد المعدل): ${m[1]}`],
  [/^(\S+) edited: (.+)$/, (m) => `عُدّلت ${m[1]}: ${m[2].split(', ').map((x) => trS(x)).join('، ')}`],
  [/^(\S+) edited$/, (m) => `عُدّلت ${m[1]}`],
  [/^(Group member|Work group|Direction|List value): (added|updated|deleted) (.+)$/, (m) => `${trS(m[1])}: ${{ added: 'أُضيف', updated: 'حُدّث', deleted: 'حُذف' }[m[2]]} ${m[3]}`],
  [/^Errors and warnings recorded by the application, newest first\. The same problem is counted on one row\. Kept for (\d+) days\.$/, (m) => `الأخطاء والتحذيرات التي سجلها التطبيق، الأحدث أولًا. تُحسب المشكلة نفسها في صف واحد. تُحفظ ${m[1]} يومًا.`],
  [/^Step (\d+)$/, (m) => `الخطوة ${m[1]}`],
  [/^Back to (\S+)$/, (m) => `العودة إلى ${m[1]}`],
  [/^Only the (\S+) team, its leader and administrators change this task\.$/, (m) => `لا يغيّر هذه المهمة إلا فريق ${m[1]} وقائده ومديرو النظام.`],
  [/^Too many failed sign-ins\. Wait (\d+) minutes, then try again\.$/, (m) => `محاولات دخول فاشلة كثيرة. انتظر ${m[1]} دقيقة ثم حاول مرة أخرى.`],
  [/^(\d+) member\(s\) of (\S+)$/, (m) => `أعضاء ${m[2]}: ${m[1]}`],
  [/^Activities start on (.+): the planned start must be on or before it\.$/, (m) => `تبدأ الأنشطة في ${m[1]}: يجب أن يكون البدء المخطط في هذا التاريخ أو قبله.`],
  [/^Activities finish on (.+): the planned finish must be on or after it\.$/, (m) => `تنتهي الأنشطة في ${m[1]}: يجب أن يكون الانتهاء المخطط في هذا التاريخ أو بعده.`],
  [/^Activities run from (.+) to (.+): the planned dates must include them\.$/, (m) => `تمتد الأنشطة من ${m[1]} إلى ${m[2]}: يجب أن تشملها التواريخ المخططة.`],
  [/^The task runs (.+) – (.+): the activity's start and finish must be inside these dates\.$/, (m) => `تمتد المهمة ${m[1]} – ${m[2]}: يجب أن يقع بدء النشاط وانتهاؤه ضمن هذه التواريخ.`],
  [/^(?:The )?start must be on or after the task's planned start \((.+)\)\.$/i, (m) => `يجب أن يكون البدء في البدء المخطط للمهمة أو بعده (${m[1]}).`],
  [/^(?:The )?finish must be on or before the task's planned finish \((.+)\)\.$/i, (m) => `يجب أن يكون الانتهاء في الانتهاء المخطط للمهمة أو قبله (${m[1]}).`],
  [/^(?:The )?start must be after predecessor (\S+) finishes \((.+)\)\.$/i, (m) => `يجب أن يكون البدء بعد انتهاء النشاط السابق ${m[1]} (${m[2]}).`],
  [/^(\S+) follows this activity and starts on (.+), so this one must finish before then\.$/, (m) => `${m[1]} يلي هذا النشاط ويبدأ في ${m[2]}، لذا يجب أن ينتهي هذا النشاط قبل ذلك.`],
  [/^This task has (\d+) activities, so it needs both planned dates\.$/, (m) => `لهذه المهمة ${m[1]} أنشطة، لذا تحتاج إلى التاريخين المخططين.`],
  [/^Activities (.+) start before this date \(the first on (.+)\)\. Move them, or pick an earlier planned start\.$/, (m) => `الأنشطة ${m[1]} تبدأ قبل هذا التاريخ (أولها في ${m[2]}). انقلها، أو اختر بدءًا مخططًا أبكر.`],
  [/^Activities (.+) finish after this date \(the last on (.+)\)\. Move them, or pick a later planned finish\.$/, (m) => `الأنشطة ${m[1]} تنتهي بعد هذا التاريخ (آخرها في ${m[2]}). انقلها، أو اختر انتهاءً مخططًا أبعد.`],
  [/^(Partner|Contribution) (\d+): write their task number like HR-T012\.$/, (m) => `${m[1] === 'Partner' ? 'الشريك' : 'المساهمة'} ${m[2]}: اكتب رقم مهمتهم بالشكل HR-T012.`],
  [/^Contribution (\d+): it must go to another work group\.$/, (m) => `المساهمة ${m[1]}: يجب أن تكون لمجموعة عمل أخرى.`],
  [/^(Partner|Contribution) (\d+): (\S+) is no longer an active work group\.$/, (m) => `${m[1] === 'Partner' ? 'الشريك' : 'المساهمة'} ${m[2]}: ${m[3]} لم تعد مجموعة عمل نشطة.`],
  [/^(.+) is no longer active\. Pick another member\.$/, (m) => `${m[1]} لم يعد نشطًا. اختر عضوًا آخر.`],
  [/^Governance · (\S+) – (.+)$/, (m) => `الحوكمة · ${m[1]} – ${m[2]}`],
  [/^(\S+) Group Leader$/, (m) => `قائد مجموعة ${m[1]}`],
  [/^The group's share of the programme, in per cent\. All groups together: (\d+)%\.$/, (m) => `حصة المجموعة من البرنامج بالنسبة المئوية. مجموع كل المجموعات: ${m[1]}%.`],
  [/^This sub-objective belongs to (\S+)\. Pick one of (\S+)'s\.$/, (m) => `هذا الهدف الفرعي يتبع ${m[1]}. اختر أحد الأهداف الفرعية لـ ${m[2]}.`],
  [/^(\S+) Team Leader$/, (m) => `قائد فريق ${m[1]}`],
  [/^(\S+) Team Coordinator$/, (m) => `منسق فريق ${m[1]}`],
  [/^(\S+) Team Member$/, (m) => `عضو فريق ${m[1]}`],
  [/^(\S+): (\S+) leader removed (partner row|contribution) \((.+?)\): (.+)$/s, (m) => `${m[1]}: أزال قائد ${m[2]} ${m[3] === 'partner row' ? 'صف الشريك' : 'المساهمة'} (${m[4]}): ${m[5]}`],
  [/^(\d+) waiting for a decision$/, (m) => `بانتظار القرار: ${m[1]}`],
  [/^(\S+) Leader$/, (m) => `قائد ${m[1]}`],
  [/^Leader: (.+)$/, (m) => `القائد: ${trS(m[1])}`],
  [/^Proposed date: (.+)$/, (m) => `التاريخ المقترح: ${m[1]}`],
  [/^Leader rejected this task: (.+)$/s, (m) => `رفض القائد هذه المهمة: ${m[1]}`],
  [/^Leader asks for clarification: (.+)$/s, (m) => `يطلب القائد توضيحًا: ${m[1]}`],
  [/^(Partner|Contribution to) (\S+): \2 leader (rejected this link|asks for clarification|asks to change the timeline)(?: \(proposed ([\d-]+)\))?(?:: (.+))?$/s, (m) => {
    const kind = m[1] === 'Partner' ? `الشريك ${m[2]}` : `مساهمة إلى ${m[2]}`;
    const what = { 'rejected this link': 'رفض قائد المجموعة هذا الرابط', 'asks for clarification': 'يطلب قائد المجموعة توضيحًا', 'asks to change the timeline': 'يطلب قائد المجموعة تغيير الجدول الزمني' }[m[3]];
    return `${kind}: ${what}${m[4] ? ` (المقترح ${m[4]})` : ''}${m[5] ? `: ${m[5]}` : ''}`;
  }],
  [/^No Direct task marked “(.+)”\.$/, (m) => `لا توجد مهمة مباشرة بحالة «${trS(m[1])}».`],
  [/^No link marked “(.+)”\.$/, (m) => `لا روابط بحالة «${trS(m[1])}».`],
  [/^(\S+) needs from (\S+)$/, (m) => `${m[1]} يحتاج من ${m[2]}`],
  [/^(\S+) delivers to (\S+)$/, (m) => `${m[1]} يقدم إلى ${m[2]}`],
  [/^(\S+) Team member$/, (m) => `عضو فريق ${m[1]}`],
  [/^(\S+) Team$/, (m) => `فريق ${m[1]}`],
];

import { trS } from './ar';
